insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a1fe2fc1-4868-5441-81f6-097a1b6bce30', 'Crossing over between non-sister chromatids of homologous chromosomes [1] in prophase I exchanges alleles, giving new combinations [1]; random orientation of bivalents in metaphase I gives different combinations of maternal and paternal chromosomes in each gamete [1].', 'Crossing over between non-sister chromatids of homologous chromosomes [1] in prophase I exchanges alleles, giving new combinations [1]; random orientation of bivalents in metaphase I gives different combinations of maternal and paternal chromosomes in each gamete [1].', '[{"text": "Marking point 1", "any": ["crossing over", "chiasma"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["prophase i", "non-sister", "exchange"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["random orientation", "independent assortment", "metaphase i"], "all": [], "marks": 1}]'::jsonb, 'Crossing over between non-sister chromatids of homologous chromosomes [1] in prophase I exchanges alleles, giving new combinations [1]; random orientation of bivalents in metaphase I gives different combinations of maternal and paternal chromosomes in each gamete [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
