insert into public.questions (id, kind, prompt, options, marks, image_url) values ('0cda9452-cf28-5583-9ad0-69cf2ca97c70', 'short', 'Explain how a pregnancy test detects hCG.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0cda9452-cf28-5583-9ad0-69cf2ca97c70', 'The test strip contains monoclonal antibodies specific to hCG [1]; hCG in urine binds to antibodies linked to coloured particles [1]; these complexes are captured by antibodies fixed at the test line, producing a coloured line [1].', 'The test strip contains monoclonal antibodies specific to hCG [1]; hCG in urine binds to antibodies linked to coloured particles [1]; these complexes are captured by antibodies fixed at the test line, producing a coloured line [1].', '[{"text": "Marking point 1", "any": ["monoclonal", "antibod"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["bind"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["line", "coloured", "fixed", "immobilised"], "all": [], "marks": 1}]'::jsonb, 'The test strip contains monoclonal antibodies specific to hCG [1]; hCG in urine binds to antibodies linked to coloured particles [1]; these complexes are captured by antibodies fixed at the test line, producing a coloured line [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('f09d323c-b0fc-59dc-88b8-4d68de01e6eb', '0cda9452-cf28-5583-9ad0-69cf2ca97c70', 27);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('07075e28-f4f8-5718-8670-c3790d3becee', 'short', 'Explain the role of positive feedback in childbirth.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('07075e28-f4f8-5718-8670-c3790d3becee', 'Oxytocin from the pituitary stimulates contractions of the uterus muscle [1]; contractions push the baby against the cervix, stretching it [1]; this stimulates more oxytocin release, so contractions intensify (positive feedback) until birth [1].', 'Oxytocin from the pituitary stimulates contractions of the uterus muscle [1]; contractions push the baby against the cervix, stretching it [1]; this stimulates more oxytocin release, so contractions intensify (positive feedback) until birth [1].', '[{"text": "Marking point 1", "any": ["oxytocin"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["contraction"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stretch", "more oxytocin", "positive feedback", "increase"], "all": [], "marks": 1}]'::jsonb, 'Oxytocin from the pituitary stimulates contractions of the uterus muscle [1]; contractions push the baby against the cervix, stretching it [1]; this stimulates more oxytocin release, so contractions intensify (positive feedback) until birth [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('f09d323c-b0fc-59dc-88b8-4d68de01e6eb', '07075e28-f4f8-5718-8670-c3790d3becee', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('3894cde0-216a-5123-9e02-4c5ee65552dd', 'short', 'Explain why early studies on HRT and coronary heart disease gave misleading conclusions.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3894cde0-216a-5123-9e02-4c5ee65552dd', 'Early studies were observational and showed only a correlation between HRT and lower heart disease [1]; a confounding factor (higher socio-economic status of women taking HRT) explained it, and randomised trials showed no protective effect [1].', 'Early studies were observational and showed only a correlation between HRT and lower heart disease [1]; a confounding factor (higher socio-economic status of women taking HRT) explained it, and randomised trials showed no protective effect [1].', '[{"text": "Marking point 1", "any": ["correlation", "observational"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["confounding", "socio-economic", "other factor", "not cause"], "all": [], "marks": 1}]'::jsonb, 'Early studies were observational and showed only a correlation between HRT and lower heart disease [1]; a confounding factor (higher socio-economic status of women taking HRT) explained it, and randomised trials showed no protective effect [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('f09d323c-b0fc-59dc-88b8-4d68de01e6eb', '3894cde0-216a-5123-9e02-4c5ee65552dd', 29);
