insert into public.questions (id, kind, prompt, options, marks, image_url) values ('652c7e2a-fe21-5146-911f-d83aa4f786b9', 'short', 'Explain the role of feedback in the menstrual cycle.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/MenstrualCycle2_en.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('652c7e2a-fe21-5146-911f-d83aa4f786b9', 'High oestradiol levels before ovulation give positive feedback, causing an LH surge [1]; after ovulation progesterone (and oestradiol) give negative feedback [1], inhibiting FSH and LH secretion so no new follicles develop [1].', 'High oestradiol levels before ovulation give positive feedback, causing an LH surge [1]; after ovulation progesterone (and oestradiol) give negative feedback [1], inhibiting FSH and LH secretion so no new follicles develop [1].', '[{"text": "Marking point 1", "any": ["positive feedback", "lh surge"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["negative feedback", "inhibit"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["progesterone"], "all": [], "marks": 1}]'::jsonb, 'High oestradiol levels before ovulation give positive feedback, causing an LH surge [1]; after ovulation progesterone (and oestradiol) give negative feedback [1], inhibiting FSH and LH secretion so no new follicles develop [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4e73906a-4012-548d-88c0-5d317b7e235f', '652c7e2a-fe21-5146-911f-d83aa4f786b9', 14);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a34ff6ec-8b53-5d9f-a521-1a1b63c84deb', 'short', 'Outline the use of hormones in IVF treatment.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a34ff6ec-8b53-5d9f-a521-1a1b63c84deb', 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].', 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].', '[{"text": "Marking point 1", "any": ["down-regulat", "stop", "suspend", "pituitary"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fsh", "many follicles", "superovulation"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["hcg", "lh", "mature", "progesterone"], "all": [], "marks": 1}]'::jsonb, 'A drug first stops the woman''s own FSH and LH secretion (down-regulation) [1]; FSH injections then stimulate many follicles to develop [1]; hCG is given to mature the eggs before collection, and progesterone supports the endometrium after transfer [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4e73906a-4012-548d-88c0-5d317b7e235f', 'a34ff6ec-8b53-5d9f-a521-1a1b63c84deb', 15);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('97cbd33a-db7b-536e-9b8a-255a69222126', 'short', 'Explain what happens to the endometrium if fertilization does not occur.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('97cbd33a-db7b-536e-9b8a-255a69222126', 'The corpus luteum degenerates so progesterone levels fall [1]; the endometrium is no longer maintained and breaks down, shed in menstruation [1].', 'The corpus luteum degenerates so progesterone levels fall [1]; the endometrium is no longer maintained and breaks down, shed in menstruation [1].', '[{"text": "Marking point 1", "any": ["corpus luteum", "degenerate", "progesterone falls"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["breaks down", "menstruation", "shed"], "all": [], "marks": 1}]'::jsonb, 'The corpus luteum degenerates so progesterone levels fall [1]; the endometrium is no longer maintained and breaks down, shed in menstruation [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
