insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cc1a9d1a-a3e7-593e-a116-0887249da0e5', 'short', 'Explain how self-incompatibility increases genetic variation within a species.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cc1a9d1a-a3e7-593e-a116-0887249da0e5', 'Pollen from the same plant is recognised and prevented from fertilising the ovules (e.g. pollen tube growth stops) [1]; so only cross-fertilisation with other plants occurs, combining genes from different parents [1].', 'Pollen from the same plant is recognised and prevented from fertilising the ovules (e.g. pollen tube growth stops) [1]; so only cross-fertilisation with other plants occurs, combining genes from different parents [1].', '[{"text": "Marking point 1", "any": ["own pollen", "recognis", "same allele", "rejected", "prevent self"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cross", "different plant", "outbreeding", "variation"], "all": [], "marks": 1}]'::jsonb, 'Pollen from the same plant is recognised and prevented from fertilising the ovules (e.g. pollen tube growth stops) [1]; so only cross-fertilisation with other plants occurs, combining genes from different parents [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('4e73906a-4012-548d-88c0-5d317b7e235f', 'cc1a9d1a-a3e7-593e-a116-0887249da0e5', 22);
