insert into public.questions (id, kind, prompt, options, marks, image_url) values ('2e829132-e56e-52ec-be8d-84e67acc79bf', 'short', 'Explain why haemophilia is more common in males than in females.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2e829132-e56e-52ec-be8d-84e67acc79bf', 'Males have only one X chromosome, so one recessive allele causes haemophilia (the Y has no allele) [1]; females need two recessive alleles, so heterozygous females are carriers without the disease [1].', 'Males have only one X chromosome, so one recessive allele causes haemophilia (the Y has no allele) [1]; females need two recessive alleles, so heterozygous females are carriers without the disease [1].', '[{"text": "Marking point 1", "any": ["one x", "single x", "only one copy", "y does not"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["two copies", "homozygous", "carrier"], "all": [], "marks": 1}]'::jsonb, 'Males have only one X chromosome, so one recessive allele causes haemophilia (the Y has no allele) [1]; females need two recessive alleles, so heterozygous females are carriers without the disease [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('35158f29-4553-51d1-824d-ec5096437641', '2e829132-e56e-52ec-be8d-84e67acc79bf', 21);
